-- Sendro Instagram / SaaS database Step 6: durable Instagram webhook inbox.
-- Operator-run migration ONLY. This DB is shared by dev and main production.
-- Requires owner approval, backup, and read-only schema preflight.
-- Creates ONE EMPTY TABLE. No WhatsApp records or code are modified.
--
-- Store only APP-ENCRYPTED raw request bodies in payload_ciphertext (BYTEA).
-- Future backend must verify Meta HMAC before encrypting and inserting.
-- Never insert plaintext DMs, passwords, API tokens or App Secrets here.
-- Inbox is INTERNAL only; do not expose rows through user-facing APIs.
--
-- A single Instagram envelope can contain events from multiple business
-- accounts, so the envelope is deliberately not bound to one tenant.
-- A future worker must validate routing to tenant+channel for EVERY event
-- before creating conversation/message records.

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

CREATE TABLE public.sendro_channel_webhook_deliveries (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    provider VARCHAR(20) NOT NULL,
    raw_body_sha256 CHAR(64) NOT NULL,
    payload_ciphertext BYTEA NOT NULL,
    processing_state VARCHAR(16) NOT NULL DEFAULT 'pending',
    attempts INTEGER NOT NULL DEFAULT 0,
    last_error_code VARCHAR(80),
    received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    next_attempt_at TIMESTAMPTZ,
    processed_at TIMESTAMPTZ,

    CONSTRAINT uq_sendro_channel_webhook_deliveries_dedupe
        UNIQUE (provider, raw_body_sha256),
    CONSTRAINT ck_sendro_channel_webhook_deliveries_provider
        CHECK (provider = 'instagram'),
    CONSTRAINT ck_sendro_channel_webhook_deliveries_digest
        CHECK (raw_body_sha256 ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_sendro_channel_webhook_deliveries_state
        CHECK (processing_state IN (
            'pending', 'processing', 'processed', 'quarantined', 'failed'
        )),
    CONSTRAINT ck_sendro_channel_webhook_deliveries_attempts
        CHECK (attempts >= 0),
    CONSTRAINT ck_sendro_channel_webhook_deliveries_ciphertext
        CHECK (OCTET_LENGTH(payload_ciphertext) > 0)
);

CREATE INDEX idx_sendro_channel_webhook_deliveries_work
    ON public.sendro_channel_webhook_deliveries
    (processing_state, next_attempt_at, id)
    WHERE processing_state IN ('pending', 'failed');

COMMIT;

-- Expected: 10 columns and 0 rows. No operations in this migration
-- acknowledge real webhooks, register Instagram accounts, or grant access.
